"use server";

import { prisma } from "@/src/lib/prisma";
import { revalidatePath } from "next/cache";
import { getServerSession } from "next-auth"; // Veya kullandığın auth kütüphanesi
import { authOptions } from "@/src/lib/auth"; // authOptions yolunu projene göre kontrol et

// Kullanıcıyı doğrulamak için yardımcı fonksiyon
async function getAuthenticatedUser() {
  const session = await getServerSession(authOptions);
  if (!session?.user?.id) return null;
  return session.user.id;
}

export async function createNewTask(data: any) {
  try {
    const userId = await getAuthenticatedUser();
    
    if (!userId) {
      return { success: false, error: "Niet ingelogd. Log opnieuw in." };
    }

    await prisma.task.create({
      data: {
        title: data.titel,
        description: JSON.stringify(data), 
        userId: userId, // Artık findFirst değil, oturumdaki gerçek ID
      },
    });

    revalidatePath("/tasks");
    return { success: true };
  } catch (error) {
    console.error("Create Error:", error);
    return { success: false, error: "Fout bij aanmaken" };
  }
}

export async function deleteTask(id: string) {
  try {
    const userId = await getAuthenticatedUser();
    if (!userId) return { success: false, error: "Niet geautoriseerd" };

    // Sadece sahibi olduğu görevi silebilmesi için güvenlik kontrolü
    await prisma.task.delete({
      where: { 
        id: id,
        userId: userId // Başkasının verisini silmesini engeller
      },
    });

    revalidatePath("/tasks");
    return { success: true };
  } catch (error) {
    console.error("Delete Error:", error);
    return { success: false };
  }
}

export async function updateTaskContent(id: string, fullData: any) {
  try {
    const userId = await getAuthenticatedUser();
    if (!userId) return { success: false };

    await prisma.task.update({
      where: { 
        id: id,
        userId: userId 
      },
      data: {
        description: JSON.stringify(fullData),
      },
    });
    
    revalidatePath("/tasks");
    return { success: true };
  } catch (error) {
    console.error("Update Error:", error);
    return { success: false };
  }
}